//! The embedded assets (generated by v2/scripts/build-harness-assets.sh) and the override layers.

use std::fs;
use std::path::{Path, PathBuf};

use amp_core::assets::{Assets, Origin, OverrideDirs};

const WORKERS: [&str; 10] = [
    "amp-worker-backend",
    "amp-worker-frontend",
    "amp-worker-docs",
    "amp-designer",
    "amp-media",
    "amp-researcher",
    "amp-github-researcher",
    "amp-reviewer",
    "amp-github-reviewer",
    "amp-kb-curator",
];

/// A fresh directory under cargo's per-test tmp dir (inside target/, never /tmp).
fn scratch(name: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("assets")
        .join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    dir
}

fn write(path: &Path, text: &str) {
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, text).unwrap();
}

#[test]
fn embedded_roster_is_the_eleven_roles() {
    let assets = Assets::embedded().unwrap();
    let ids: Vec<&str> = assets.agents().map(|a| a.id.as_str()).collect();
    assert_eq!(ids.len(), 11, "{ids:?}");
    let manager = assets.agent("amp-manager").unwrap();
    assert!(manager.is_primary());
    assert_eq!(assets.default_agent().unwrap().id, "amp-manager");
    for id in WORKERS {
        let a = assets.agent(id).unwrap_or_else(|| panic!("missing {id}"));
        assert_eq!(a.mode(), "subagent", "{id}");
        assert!(a.origin.is_embedded());
        assert!(!a.description.is_empty() && !a.prompt.is_empty());
        // Permissions stay in the frontmatter for the tool policy (M2-2).
        assert!(a.frontmatter.get("permission").is_some(), "{id}");
    }
    assert_eq!(assets.manifest().source_sha256.len(), 64);
}

#[test]
fn embedded_skills_exclude_agent_builder_and_keep_files() {
    let assets = Assets::embedded().unwrap();
    assert!(assets.skill("amp-agent-builder").is_none());
    assert_eq!(assets.manifest().excluded_skills, ["amp-agent-builder"]);
    for name in [
        "amp-index",
        "amp-mcp",
        "amp-planning",
        "amp-execution",
        "amp-review",
        "amp-kb",
        "amp-init",
        "amp-day-report",
    ] {
        let s = assets
            .skill(name)
            .unwrap_or_else(|| panic!("missing {name}"));
        assert!(!s.description.is_empty() && !s.content.is_empty());
    }
    let go = assets.skill("go-engineer").unwrap();
    assert!(go.files.contains_key("examples.md"));
    let tools = assets.skill("amp-design-tools").unwrap();
    assert!(tools.files.contains_key("scripts/publish_file.py"));
}

#[test]
fn embedded_markdown_has_no_host_glue() {
    let assets = Assets::embedded().unwrap();
    let banned = [
        "amp_amp_",
        "subagent_depth",
        ".opencode/",
        "opencode",
        "`task` tool",
        "skill(\"",
        "amp-agent-builder",
    ];
    let mut texts: Vec<(String, String)> = assets
        .agents()
        .map(|a| (a.id.clone(), a.prompt.clone()))
        .collect();
    for s in assets.skills() {
        for (rel, f) in &s.files {
            if rel.ends_with(".md") {
                texts.push((
                    format!("{}/{rel}", s.name),
                    String::from_utf8(f.bytes.clone()).unwrap(),
                ));
            }
        }
    }
    for (name, text) in &texts {
        // amp-planning credits Anthropic's guidance; that's attribution, not glue.
        for b in banned {
            assert!(!text.contains(b), "{name} still contains {b:?}");
        }
    }
    let manager = assets.agent("amp-manager").unwrap();
    assert!(manager.prompt.contains("amp_run_ticket"));
    // The manager may no longer edit .opencode/** or opencode.json.
    let edit = &manager.frontmatter["permission"]["edit"];
    assert_eq!(edit.as_object().unwrap().len(), 1, "{edit}");
    assert_eq!(edit["*"], "deny");
}

#[test]
fn overrides_layer_repo_over_user_over_embedded() {
    let root = scratch("layers");
    let user = root.join("user");
    let repo = root.join("repo");

    // User replaces a worker; repo replaces the same worker again (repo wins) and adds a new one.
    write(
        &user.join("agents/amp-worker-docs.md"),
        "---\ndescription: user docs\nmode: subagent\n---\nUser prompt.\n",
    );
    write(
        &repo.join("agents/amp-worker-docs.md"),
        "---\ndescription: repo docs\nmode: subagent\n---\nRepo prompt.\n",
    );
    write(
        &user.join("agents/amp-worker-backend.md"),
        "---\ndescription: user backend\n---\nUser backend.\n",
    );
    write(
        &repo.join("agents/amp-worker-rust.md"),
        "---\ndescription: Rust specialist\nmode: subagent\n---\nRust.\n",
    );
    write(&repo.join("agents/notes.txt"), "ignored: not .md");

    // Skills: per-file. User overrides amp-kb's SKILL.md only; repo adds a file and a new skill.
    write(
        &user.join("skills/amp-kb/SKILL.md"),
        "---\nname: amp-kb\ndescription: user kb\n---\nUser KB rules.\n",
    );
    write(&repo.join("skills/go-engineer/extra.md"), "Repo extra.\n");
    write(
        &repo.join("skills/rust-engineer/SKILL.md"),
        "---\nname: rust-engineer\ndescription: Rust patterns\n---\nUse 1.98.1.\n",
    );

    let dirs = OverrideDirs {
        user: Some(user.clone()),
        repo: Some(repo.clone()),
    };
    let assets = Assets::load(&dirs).unwrap();

    let docs = assets.agent("amp-worker-docs").unwrap();
    assert_eq!(docs.description, "repo docs");
    assert_eq!(docs.prompt, "Repo prompt.");
    assert_eq!(
        docs.origin,
        Origin::Repo(repo.join("agents/amp-worker-docs.md"))
    );
    let backend = assets.agent("amp-worker-backend").unwrap();
    assert_eq!(backend.prompt, "User backend.");
    assert!(matches!(backend.origin, Origin::User(_)));
    assert_eq!(backend.mode(), "subagent");
    assert!(assets.agent("amp-worker-rust").is_some());
    assert!(assets.agent("notes").is_none());
    assert!(assets.agent("amp-manager").unwrap().origin.is_embedded());
    assert_eq!(assets.agents().count(), 12);

    let kb = assets.skill("amp-kb").unwrap();
    assert_eq!(kb.content, "User KB rules.");
    assert!(matches!(kb.origin(), Origin::User(_)));
    let go = assets.skill("go-engineer").unwrap();
    assert!(go.origin().is_embedded());
    assert!(go.files["examples.md"].origin.is_embedded());
    assert!(matches!(go.files["extra.md"].origin, Origin::Repo(_)));
    assert_eq!(
        assets.skill("rust-engineer").unwrap().description,
        "Rust patterns"
    );

    // Without overrides, the embedded versions come back.
    let plain = Assets::embedded().unwrap();
    assert_ne!(
        plain.agent("amp-worker-docs").unwrap().prompt,
        "Repo prompt."
    );
}

#[test]
fn malformed_overrides_are_errors_naming_the_file() {
    let cases: [(&str, &str, &str); 5] = [
        ("agents/amp-x.md", "no frontmatter at all\n", "description"),
        (
            "agents/amp-x.md",
            "---\ndescription: [oops\n---\nbody\n",
            "YAML",
        ),
        (
            "agents/Bad_Name.md",
            "---\ndescription: d\n---\nbody\n",
            "lowercase",
        ),
        (
            "skills/my-skill/SKILL.md",
            "---\nname: other\ndescription: d\n---\nbody\n",
            "must match",
        ),
        (
            "skills/my-skill/notes.md",
            "no SKILL.md here\n",
            "no SKILL.md",
        ),
    ];
    for (i, (rel, text, want)) in cases.iter().enumerate() {
        let user = scratch(&format!("bad{i}"));
        write(&user.join(rel), text);
        let err = Assets::load(&OverrideDirs {
            user: Some(user.clone()),
            repo: None,
        })
        .unwrap_err()
        .to_string();
        assert!(err.contains(want), "{rel}: {err}");
        let leaf = Path::new(rel).parent().unwrap().file_name().unwrap();
        assert!(
            err.contains(rel) || err.contains(leaf.to_str().unwrap()),
            "{rel}: {err}"
        );
    }
}

#[test]
fn missing_override_dirs_are_fine() {
    let root = scratch("missing");
    let assets = Assets::load(&OverrideDirs {
        user: Some(root.join("nope")),
        repo: Some(root.join("nope2")),
    })
    .unwrap();
    assert_eq!(assets.agents().count(), 11);
}

#[test]
fn materialized_skills_are_readable_rpi_skills() {
    let dest = scratch("materialize");
    let assets = Assets::embedded().unwrap();
    let skills = assets.materialize_skills(&dest).unwrap();
    assert_eq!(skills.len(), assets.skills().count());
    let exec = skills.iter().find(|s| s.name == "amp-execution").unwrap();
    assert_eq!(
        Path::new(&exec.file_path),
        dest.join("amp-execution/SKILL.md")
    );
    let on_disk = fs::read_to_string(&exec.file_path).unwrap();
    assert!(on_disk.starts_with("---\nname: amp-execution"));
    assert!(on_disk.contains(&exec.content));
    assert!(
        dest.join("amp-design-tools/scripts/publish_file.py")
            .is_file()
    );
}
